const names = {"52": "Santander M\u00e9rida", "71": "Santander Concentradora", "72": "Santander Canc\u00fan y Playa", "73": "Santander Campeche", "74": "Santander Chetumal", "75": "BBVA Bancomer", "76": "Get Net M\u00e9rida 1", "77": "Get Net M\u00e9rida 2", "78": "Get Net Canc\u00fan", "79": "Get Net Playa", "80": "Get Net Ticul", "81": "Get Net Campeche", "82": "Get Net Chetumal"};
const rows = ($('Buscar Por Conciliar').first().json.result || []).map(r => ({
  journalId: r.journal_id[0],
  name: names[r.journal_id[0]] || r.journal_id[1],
  count: r.journal_id_count || r.__count || 0
})).sort((a, b) => b.count - a.count);
const total = rows.reduce((s, r) => s + r.count, 0);

const lines = $json.result || [];
const byJournal = {};
for (const l of lines) {
  const jid = l.journal_id[0];
  if (!byJournal[jid]) byJournal[jid] = [];
  if (byJournal[jid].length < 3) byJournal[jid].push(l);
}

let text = `🏦 <b>Resumen de Conciliacion Bancaria</b>\n<b>${total}</b> transaccion(es) por conciliar en total:\n\n`;
for (const r of rows) {
  text += `• <b>${r.name}</b>: ${r.count} por conciliar\n`;
  const oldest = byJournal[r.journalId] || [];
  for (const l of oldest) {
    text += `   ↳ ${l.date} — ${l.payment_ref || 'sin descripcion'} ($${l.amount})\n`;
  }
}
text += `\n<i>Se muestran hasta 3 transacciones mas antiguas por diario. Resumen ligero por Telegram — esta base no tiene el modulo Enterprise de conciliacion (account_accountant), asi que no hay vista kanban con auto-matching en Odoo mismo todavia.</i>`;

return [{ json: { text } }];

const err = $input.first().json;
const detalle = err.error?.message ?? err.message ?? JSON.stringify(err);
return [{ json: { text: `🔴 <b>Resumen Conciliacion: fallo al autenticar contra Odoo</b>\nDetalle: <code>${detalle}</code>` } }];

